"""Offline whole-corpus recall explorer with exact denominators and source annotations."""
import html
import json
from pathlib import Path


def render(receipts, annotation, coding, benchmark):
    records={key:{'organism':value['organism'],'definition':value['definition'],
                  'features':value['features']} for key,value in annotation['records'].items()}
    payload={'runs':receipts,'records':records,'coding':coding,'benchmark':benchmark}
    encoded=json.dumps(payload,separators=(',',':'),ensure_ascii=True).replace('<','\\u003c').replace('&','\\u0026')
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PerfectPower | Whole-corpus BLAST recall</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172638;font:16px/1.5 system-ui}main{max-width:1180px;margin:auto;padding:32px 24px}h1{font-size:clamp(28px,4vw,43px);line-height:1.15}header{border-bottom:3px solid #148373;padding-bottom:24px}small{color:#526475}section{background:white;border:1px solid #dce2e8;border-radius:12px;padding:22px;margin-top:20px}.controls{display:flex;gap:18px;flex-wrap:wrap}label{display:grid;gap:6px}input,select,button{font:inherit;padding:8px;border:1px solid #9dabb8;border-radius:5px}button{cursor:pointer;background:#164d64;color:white}.metrics{display:flex;gap:25px;flex-wrap:wrap;padding:18px 0}.metric b{display:block;font-size:28px;color:#116b60}.scroll{overflow:auto;max-height:480px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;text-align:left;border-bottom:1px solid #e5e9ed}th{position:sticky;top:0;background:#eaf0f5}tr.miss{background:#fff2e5}details{padding:12px 0}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.scope{border-left:4px solid #d59236;padding-left:15px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:700px){main{padding:20px 12px}.columns{grid-template-columns:1fr}section{padding:15px}}a{color:#12645f}
</style><main><header><small>PERFECTPOWER / SOURCE-BOUND EXPERIMENT</small><h1>Whole-corpus BLAST recall</h1><p>930 pinned RefSeq insulin-gene mRNAs · 628,656 bases · three insulin-family queries · 2,790 complete pairs · both strands.</p><p class="scope">This is the complete corpus returned by the recorded Entrez search. It measures score-threshold retrieval recall on that finite corpus. It does not measure nt/nr completeness or biological orthology.</p></header>
<section><div class="controls"><label>BLAST word size<select id="word"><option>7</option><option>11</option><option>28</option></select></label><label>Exact score threshold<select id="threshold"><option>40</option><option selected>100</option><option>200</option></select></label><label>Query<select id="query"><option value="">All queries</option></select></label><label>Accession or organism<input id="filter" placeholder="Human, NM_..." aria-label="Filter pairs"></label><label>Pair display<select id="status"><option value="all">All reference positives</option><option value="miss">Missed positives</option><option value="found">Recovered positives</option><option value="matrix">Entire pair universe</option></select></label></div><div class="metrics" id="metrics"></div><button id="download">Download complete selected recall receipt</button><p id="count"></p><div class="scroll"><table><thead><tr><th>Query</th><th>Subject</th><th>Organism</th><th>Exact optimum</th><th>BLAST best</th><th>Deficit</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section class="columns"><div><h2>Source annotation</h2><p>Choose a subject row to inspect all supplied features, qualifiers, and the CDS translation audit.</p><div id="annotation">Every one of the 931 database/query source records is annotated. Complete original XML remains in the source package.</div></div><div><h2>Count machinery benchmark</h2><p>Three trials per case. The small cases compare the same path population with independent enumeration; large cases retain the exact compressed population.</p><div id="bench"></div><p>These timings compare representations of HSP chains. They are not a BLAST speedup measurement.</p></div></section>
<section><h2>What the evidence establishes</h2><p>All 162,253 reported HSPs pass two independent executable source replays. Lean 4.20 checks the general path recurrence, decreasing-rank completeness, and BTOP decoder soundness. Literal kernel certificates cover all 624 HSPs of the word-28 run. The word-7 and word-11 literal runs have executable audits; they are not claimed as kernel-instantiated.</p><p>The reference scanner exhaustively scores every query/database pair, both strands, with match 2, mismatch -3, and affine gap cost 5 + 2 × length. Its independent Python crosscheck covers 123 sequence pairs, or 246 strand scores. Default statistical significance and biological function are distinct questions.</p><p>Full NCBI feature annotations and original source bytes are retained. CDS audits: 914 literal agreements, nine ambiguous coding sequences, eight exception cases. None of the unresolved records is silently accepted.</p></section></main><script id="evidence" type="application/json">__EVIDENCE__</script><script>
const E=JSON.parse(document.getElementById('evidence').textContent), $=id=>document.getElementById(id);
function node(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}
const queries=[...new Set(E.runs['7'].pairs.map(p=>p.query))];for(const q of queries){let o=node('option',q);o.value=q;$('query').append(o);}
function showAnnotation(id){const r=E.records[id],root=$('annotation');root.replaceChildren(node('h3',id),node('p',r.organism+' · '+r.definition));for(let k=0;k<r.features.length;k++){let d=document.createElement('details');d.append(node('summary',r.features[k].key+' · '+r.features[k].location),node('pre',JSON.stringify(r.features[k],null,2)));root.append(d);}let d=document.createElement('details');d.append(node('summary','CDS translation audit'),node('pre',JSON.stringify(E.coding.records[id],null,2)));root.append(d);}
function redraw(){const run=E.runs[$('word').value],t=Number($('threshold').value),q=$('query').value;let all=run.pairs.filter(p=>!q||p.query===q),positive=all.filter(p=>p.reference_score>=t),found=positive.filter(p=>Number(p.blast_best_score)>=t);$('metrics').replaceChildren();for(const [a,b] of [['Positive pairs',positive.length],['Recovered',found.length],['Missed',positive.length-found.length],['Recall',positive.length?(100*found.length/positive.length).toFixed(2)+'%':'undefined']]){const d=node('div',a);d.className='metric';d.prepend(node('b',b));$('metrics').append(d);}const f=$('filter').value.toLowerCase(),st=$('status').value;let list=(st==='matrix'?all:positive).filter(p=>(st!=='miss'||Number(p.blast_best_score)<t)&&(st!=='found'||Number(p.blast_best_score)>=t)&&(!f||(p.query+' '+p.subject+' '+E.records[p.subject].organism).toLowerCase().includes(f)));$('count').textContent=list.length+' pairs shown; complete selected-query universe: '+all.length+'.';$('rows').replaceChildren();for(const p of list){let tr=document.createElement('tr');if(p.reference_score>=t&&Number(p.blast_best_score)<t)tr.className='miss';for(const text of [p.query,p.subject,E.records[p.subject].organism,p.reference_score,p.blast_best_score,p.score_deficit])tr.append(node('td',text));tr.addEventListener('click',()=>showAnnotation(p.subject));tr.tabIndex=0;tr.addEventListener('keydown',e=>{if(e.key==='Enter')showAnnotation(p.subject);});$('rows').append(tr);}}
for(const id of ['word','threshold','query','status'])$(id).addEventListener('change',redraw);$('filter').addEventListener('input',redraw);
$('download').addEventListener('click',()=>{const b=new Blob([JSON.stringify(E.runs[$('word').value],null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='recall_word'+$('word').value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});
for(const c of E.benchmark.cases){let d=document.createElement('details');d.append(node('summary',c.vertices+' HSPs · '+c.population+' chains · '+(1000*c.index_median_seconds).toFixed(2)+' ms'),node('pre',JSON.stringify(c,null,2)));$('bench').append(d);}redraw();
</script>'''.replace('__EVIDENCE__',encoded)


def write_report(directory,output):
    import gzip
    directory=Path(directory)
    receipts={str(w):json.loads((directory/f'recall_word{w}.json').read_text()) for w in (7,11,28)}
    annotation=json.loads(gzip.decompress((directory/'annotation_word28.json.gz').read_bytes()))
    coding=json.loads((directory/'coding_annotation.json').read_text());benchmark=json.loads((directory/'benchmark.json').read_text())
    output=Path(output);output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(render(receipts,annotation,coding,benchmark));return output
